/**
 * Pipedrive Node - Version 2
 * Discriminator: resource=file, operation=get
 */


interface Credentials {
  pipedriveApi: CredentialReference;
  pipedriveOAuth2Api: CredentialReference;
}

/** Get an activity */
export type PipedriveV2FileGetParams = {
  resource: 'file';
  operation: 'get';
  authentication?: 'apiToken' | 'oAuth2' | Expression<string>;
/**
 * ID of the file to get
 * @default 0
 */
    fileId?: number | Expression<number>;
};

export type PipedriveV2FileGetOutput = {
  active_flag?: boolean;
  activity_id?: unknown;
  add_time?: string;
  cid?: unknown;
  deal_id?: number;
  deal_name?: string;
  description?: unknown;
  file_name?: string;
  file_size?: number;
  file_type?: string;
  id?: number;
  inline_flag?: boolean;
  lead_id?: unknown;
  lead_name?: unknown;
  log_id?: unknown;
  mail_message_id?: unknown;
  mail_template_id?: unknown;
  name?: string;
  org_id?: number;
  org_name?: string;
  person_id?: number;
  person_name?: string;
  product_id?: unknown;
  product_name?: unknown;
  remote_id?: string;
  remote_location?: string;
  s3_bucket?: unknown;
  update_time?: string;
  url?: string;
  user_id?: number;
};

export type PipedriveV2FileGetNode = {
  type: 'n8n-nodes-base.pipedrive';
  version: 2;
  config: NodeConfig<PipedriveV2FileGetParams> & { credentials?: Credentials };
  output?: Items<PipedriveV2FileGetOutput>;
};